            "조문이동이후": "",
            "조문여부": "전문"
        },
        {
            "조문번호": "24",
            "조문시행일자": "20260701",
            "조문변경여부": "N",
            "조문이동이전": "",
            "조문참고자료": "[전문개정 2009.2.6][제목개정 2011.4.14]",
            "조문키": "0024001",
            "항": [
                {
                    "항번호": "①",
                    "항내용": "① 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 관할 구역에 대하여 도시ㆍ군관리계획을 입안하여야 한다. <개정 2011.4.14>"
                },
                {
                    "항번호": "②",
                    "항내용": "② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수는 다음 각 호의 어느 하나에 해당하면 인접한 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역 전부 또는 일부를 포함하여 도시ㆍ군관리계획을 입안할 수 있다. <개정 2011.4.14>",
                    "호": [
                        {
                            "호번호": "1.",
                            "호내용": "1. 지역여건상 필요하다고 인정하여 미리 인접한 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수와 협의한 경우"
                        },
                        {
                            "호번호": "2.",
                            "호내용": "2. 제18조제2항에 따라 인접한 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역을 포함하여 도시ㆍ군기본계획을 수립한 경우"
                        }
                    ]
                },
                {
                    "항번호": "③",
                    "항내용": "③ 제2항에 따른 인접한 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역에 대한 도시ㆍ군관리계획은 관계 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수가 협의하여 공동으로 입안하거나 입안할 자를 정한다. <개정 2011.4.14>"
                },
                {
                    "항번호": "④",
                    "항내용": "④ 제3항에 따른 협의가 성립되지 아니하는 경우 도시ㆍ군관리계획을 입안하려는 구역이 같은 도의 관할 구역에 속할 때에는 관할 도지사가, 둘 이상의 시ㆍ도의 관할 구역에 걸쳐 있을 때에는 국토교통부장관(제40조에 따른 수산자원보호구역의 경우 해양수산부장관을 말한다. 이하 이 조에서 같다)이 입안할 자를 지정하고 그 사실을 고시하여야 한다. <개정 2011.4.14, 2013.3.23>"
                },
                {
                    "항번호": "⑤",
                    "항내용": "⑤ 국토교통부장관은 제1항이나 제2항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 직접 또는 관계 중앙행정기관의 장의 요청에 의하여 도시ㆍ군관리계획을 입안할 수 있다. 이 경우 국토교통부장관은 관할 시ㆍ도지사 및 시장ㆍ군수의 의견을 들어야 한다. <개정 2011.4.14, 2013.3.23>",
                    "호": [
                        {
                            "호번호": "1.",
                            "호내용": "1. 국가계획과 관련된 경우"
                        },
                        {
                            "호번호": "2.",
                            "호내용": "2. 둘 이상의 시ㆍ도에 걸쳐 지정되는 용도지역ㆍ용도지구 또는 용도구역과 둘 이상의 시ㆍ도에 걸쳐 이루어지는 사업의 계획 중 도시ㆍ군관리계획으로 결정하여야 할 사항이 있는 경우"
                        },
                        {
                            "호번호": "3.",
                            "호내용": "3. 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수가 제138조에 따른 기한까지 국토교통부장관의 도시ㆍ군관리계획 조정 요구에 따라 도시ㆍ군관리계획을 정비하지 아니하는 경우"
                        }
                    ]
                },
                {
                    "항번호": "⑥",
                    "항내용": "⑥ 도지사는 제1항이나 제2항에도 불구하고 다음 각 호의 어느 하나의 경우에는 직접 또는 시장이나 군수의 요청에 의하여 도시ㆍ군관리계획을 입안할 수 있다. 이 경우 도지사는 관계 시장 또는 군수의 의견을 들어야 한다. <개정 2011.4.14>",
                    "호": [
                        {
                            "호번호": "1.",
                            "호내용": "1. 둘 이상의 시ㆍ군에 걸쳐 지정되는 용도지역ㆍ용도지구 또는 용도구역과 둘 이상의 시ㆍ군에 걸쳐 이루어지는 사업의 계획 중 도시ㆍ군관리계획으로 결정하여야 할 사항이 포함되어 있는 경우"
                        },
                        {
                            "호번호": "2.",
                            "호내용": "2. 도지사가 직접 수립하는 사업의 계획으로서 도시ㆍ군관리계획으로 결정하여야 할 사항이 포함되어 있는 경우"
                        }
                    ]
                }
            ],
            "조문내용": "제24조(도시ㆍ군관리계획의 입안권자)",
            "조문제목": "도시ㆍ군관리계획의 입안권자",
            "조문이동이후": "",
